function gameById(id){return BEGINNER_GAMES.find(g=>g.id===id)}
function trackUnlocked(trackId){const gate=TRACK_GATES[trackId];return !gate||state.gameProgress?.[gate]?.completed===true}
function trackGate(trackId){const id=TRACK_GATES[trackId];return id?gameById(id):null}
function gameUnlocked(game){return !game.requires||state.gameProgress?.[game.requires]?.completed===true}
function starsFor(hearts){return hearts>=3?3:hearts===2?2:1}
function renderGames(){
 crumb('闯关乐园');
 const completed=BEGINNER_GAMES.filter(g=>state.gameProgress?.[g.id]?.completed).length;
 $('#main').innerHTML=`<div class="route-head"><div><span class="eyebrow">LEARN BY PLAYING · 玩着学</span><h1>闯关乐园</h1><p>点选、排序、输入、找 Bug。答错不会丢进度，解释清楚后马上重试。</p></div><span class="xp-badge">⭐ ${completed} / ${BEGINNER_GAMES.length} 关</span></div><section class="game-rules"><div><b>❤️ 每局 3 颗爱心</b><span>答错扣 1 颗，归零后可立即重来</span></div><div><b>🔥 连对记录</b><span>连续答对越多，星星越多</span></div><div><b>📒 自动错题本</b><span>保存题目、正确答案和解释</span></div></section><div class="game-grid">${BEGINNER_GAMES.map((g,i)=>{const p=state.gameProgress?.[g.id],locked=!gameUnlocked(g);return `<article class="game-card ${locked?'locked':''}" style="--game:${g.color}"><span class="game-icon">${g.icon}</span><span class="eyebrow">LEVEL ${String(i+1).padStart(2,'0')}</span><h2>${esc(g.title)}</h2><p>${esc(g.desc)}</p><div class="game-stars" aria-label="获得星星">${p?.completed?'★'.repeat(p.stars)+'☆'.repeat(3-p.stars):'☆☆☆'}</div><p class="muted">${locked?'🔒 先完成 '+esc(gameById(g.requires)?.title||'前一关'):p?.completed?'已通关 · 最长连对 '+p.bestStreak:esc(g.unlock||'自由挑战')}</p><a class="${locked?'secondary disabled':'primary'}" ${locked?'aria-disabled="true"':`href="#game/${g.id}"`}>${locked?'尚未解锁':p?.completed?'再次挑战':'开始闯关'} →</a></article>`}).join('')}</div>${state.wrongBook?.length?`<section class="project-stage wrong-book"><h2>📒 最近错题</h2>${state.wrongBook.slice(-6).reverse().map(w=>`<details><summary>${esc(w.prompt)}</summary><p><b>正确思路：</b>${esc(w.answer)}</p></details>`).join('')}</section>`:''}`;
}
function renderRoundInput(round,selected=[]){
 if(round.type==='choice')return `<div class="game-options">${round.options.map((o,i)=>`<button class="game-option" data-game-choice="${i}">${esc(o)}</button>`).join('')}</div>`;
 if(round.type==='typing')return `<label class="game-input-label">在这里输入答案<input id="game-input" class="game-input" autocomplete="off" placeholder="输入后点击提交"></label><button class="primary" id="game-submit">提交答案</button>`;
 if(round.type==='order')return `<p class="muted">按正确顺序逐个点击。点错顺序可以“清空重排”。</p><div class="order-result" id="order-result">${selected.length?selected.map(esc).join(' → '):'等待选择…'}</div><div class="game-options">${round.items.map((o,i)=>`<button class="game-option" data-order="${i}" ${selected.includes(o)?'disabled':''}>${esc(o)}</button>`).join('')}</div><button class="secondary" id="order-reset">清空重排</button> <button class="primary" id="game-submit">提交顺序</button>`;
 return '';
}
function answerText(round){return Array.isArray(round.answer)?round.answer.join(' → '):round.type==='choice'?round.options[round.answer]:String(round.answer)}
function isRoundCorrect(round,value){
 if(round.type==='choice')return Number(value)===round.answer;
 if(round.type==='order')return JSON.stringify(value)===JSON.stringify(round.answer);
 const got=String(value??'').trim().toLowerCase(),answers=[round.answer,...(round.aliases||[])].map(x=>String(x).trim().toLowerCase());return answers.includes(got);
}
function renderGame(id){
 const game=gameById(id);if(!game){go('#games');return}if(!gameUnlocked(game)){toast('先完成前一关，再来挑战这里。');go('#games');return}
 crumb(game.title);let roundIndex=0,hearts=3,streak=0,best=0,selected=[];
 const shell=()=>{$('#main').innerHTML=`<a class="back-link" href="#games">← 返回闯关乐园</a><div class="game-stage" style="--game:${game.color}"><div class="game-hud"><b>${game.icon} ${esc(game.title)}</b><span id="game-hearts">❤️❤️❤️</span><span id="game-streak">🔥 0 连对</span></div><div class="game-progress"><i id="game-progress"></i></div><div id="game-board"></div></div>`};
 const draw=()=>{const r=game.rounds[roundIndex];selected=[];$('#game-progress').style.width=(roundIndex/game.rounds.length*100)+'%';$('#game-board').innerHTML=`<span class="eyebrow">第 ${roundIndex+1} / ${game.rounds.length} 题</span><h1>${esc(r.prompt)}</h1><div id="round-input">${renderRoundInput(r,selected)}</div><div id="round-feedback" class="round-feedback" role="status"></div>`;bind(r)};
 const bind=r=>{document.querySelectorAll('[data-game-choice]').forEach(b=>b.onclick=()=>judge(r,Number(b.dataset.gameChoice)));if($('#game-input')){$('#game-input').focus();$('#game-input').onkeydown=e=>{if(e.key==='Enter')judge(r,e.target.value)};$('#game-submit').onclick=()=>judge(r,$('#game-input').value)}if(r.type==='order'){document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{selected.push(r.items[Number(b.dataset.order)]);$('#round-input').innerHTML=renderRoundInput(r,selected);bind(r)});$('#order-reset').onclick=()=>{selected=[];$('#round-input').innerHTML=renderRoundInput(r,selected);bind(r)};$('#game-submit').onclick=()=>judge(r,selected)}};
 const judge=(r,value)=>{if(isRoundCorrect(r,value)){streak++;best=Math.max(best,streak);$('#game-streak').textContent='🔥 '+streak+' 连对';$('#round-feedback').className='round-feedback success';$('#round-feedback').innerHTML=`<b>答对了！</b><p>${esc(r.why)}</p><button class="primary" id="next-round">${roundIndex===game.rounds.length-1?'领取星星':'下一题'} →</button>`;document.querySelectorAll('#round-input button,#round-input input').forEach(e=>e.disabled=true);$('#next-round').onclick=()=>{roundIndex++;roundIndex>=game.rounds.length?finish():draw()}}else{hearts--;streak=0;$('#game-streak').textContent='🔥 0 连对';$('#game-hearts').textContent='❤️'.repeat(hearts)+'🤍'.repeat(3-hearts);state.wrongBook=[...(state.wrongBook||[]),{game:game.id,prompt:r.prompt,answer:answerText(r)+'。'+r.why,at:new Date().toISOString()}].slice(-100);save();$('#round-feedback').className='round-feedback error';$('#round-feedback').innerHTML=`<b>这次还没答对</b><p>${esc(r.why)}</p><p><b>正确答案：</b>${esc(answerText(r))}</p><button class="primary" id="retry-round">${hearts>0?'我明白了，再试一次':'爱心用完，重新开始'}</button>`;document.querySelectorAll('#round-input button,#round-input input').forEach(e=>e.disabled=true);$('#retry-round').onclick=()=>{if(hearts<=0){roundIndex=0;hearts=3;streak=0;best=0;$('#game-hearts').textContent='❤️❤️❤️';$('#game-streak').textContent='🔥 0 连对'}draw()}}};
 const finish=()=>{const stars=starsFor(hearts),old=state.gameProgress?.[game.id]||{};state.gameProgress[game.id]={completed:true,stars:Math.max(stars,old.stars||0),bestStreak:Math.max(best,old.bestStreak||0),attempts:(old.attempts||0)+1};save();$('#game-progress').style.width='100%';$('#game-board').innerHTML=`<div class="game-finish"><div class="celebrate">🎉</div><h1>闯关成功</h1><div class="earned-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>本关首次完成记入 60 XP。你现在可以继续下一阶段。</p><a class="primary" href="#path">回到学习路径 →</a> <a class="secondary" href="#games">选择其他关卡</a></div>`};
 shell();draw();
}
function addBeginnerPanels(){
 const l=getLesson();if(!l.vocab?.length&&!l.mini)return;
 const panel=document.createElement('section');panel.className='project-stage beginner-panel';panel.innerHTML=`<span class="eyebrow">先认零件，再动手</span>${l.vocab?.length?'<h2>本节小词典</h2>':''}${l.vocab?.length?`<div class="vocab-grid">${l.vocab.map(v=>`<div><b>${esc(v[0])}</b><span>${esc(v[1])}</span></div>`).join('')}</div>`:''}${l.rescue?.length?`<details class="rescue"><summary>卡住了，点这里自救</summary><ol>${l.rescue.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details>`:''}${l.mini?`<div class="lesson-mini"><h2>🎮 30 秒小游戏</h2><p>${esc(l.mini.prompt)}</p><div id="lesson-mini-input"></div><div id="lesson-mini-feedback" role="status"></div></div>`:''}`;
 const workspace=document.querySelector('.workspace');workspace?workspace.before(panel):$('#main').append(panel);if(l.mini)bindLessonMini(l);
}
function bindLessonMini(l){const m=l.mini,box=$('#lesson-mini-input'),feedback=$('#lesson-mini-feedback');let picked=[];
 const complete=()=>{if(!state.miniDone[l.id]){state.miniDone[l.id]=true;save()}feedback.className='round-feedback success';feedback.innerHTML='<b>✓ 小游戏完成，首次 +5 XP</b><p>现在回头看课程里的同一个概念，会更容易理解。</p>'};
 const fail=why=>{feedback.className='round-feedback error';feedback.textContent=why||'再试一次。答错不会影响课程进度。'};
 if(m.type==='choice'){box.innerHTML=`<div class="game-options">${m.options.map((o,i)=>`<button class="game-option" data-mini-choice="${i}">${esc(o)}</button>`).join('')}</div>`;box.querySelectorAll('[data-mini-choice]').forEach(b=>b.onclick=()=>Number(b.dataset.miniChoice)===m.answer?complete():fail('还不是这个。重新读一遍题目，再选。'))}
 else if(m.type==='typing'||m.type==='machine'){box.innerHTML=`<input class="game-input" id="mini-text" autocomplete="off" placeholder="在这里输入"><button class="primary" id="mini-submit">检查</button>`;$('#mini-submit').onclick=()=>String($('#mini-text').value).trim().toLowerCase()===String(m.target||m.answer).trim().toLowerCase()?complete():fail('还差一点，请核对每个字符。')}
 else if(m.type==='order'||m.type==='targets'){const answer=m.answer||m.items;box.innerHTML=`<div class="order-result" id="mini-order">等待选择…</div><div class="game-options">${m.items.map((o,i)=>`<button class="game-option" data-mini-order="${i}">${esc(o)}</button>`).join('')}</div><button class="secondary" id="mini-reset">清空</button>`;box.querySelectorAll('[data-mini-order]').forEach(b=>b.onclick=()=>{picked.push(m.items[Number(b.dataset.miniOrder)]);b.disabled=true;$('#mini-order').textContent=picked.join(' → ');if(picked.length===answer.length)(JSON.stringify(picked)===JSON.stringify(answer)?complete():fail('顺序还不对，清空后重新排。'))});$('#mini-reset').onclick=()=>{picked=[];bindLessonMini(l)}}
 else if(m.type==='match'){box.innerHTML=m.pairs.map((p,i)=>`<label class="match-row">${esc(p[0])}<select data-match="${i}"><option value="">请选择</option>${m.pairs.map(x=>`<option>${esc(x[1])}</option>`).join('')}</select></label>`).join('')+'<button class="primary" id="mini-submit">检查匹配</button>';$('#mini-submit').onclick=()=>[...box.querySelectorAll('[data-match]')].every((s,i)=>s.value===m.pairs[i][1])?complete():fail('还有匹配不对。想想它保存的是数字、文字还是真假。')}
 if(state.miniDone[l.id]){feedback.className='round-feedback success';feedback.textContent='✓ 你已经完成过这个小游戏，可以随时重玩。'}
}
